/**
 * Build the README banner, the GitHub social preview and the README screenshots.
 *
 * Usage (from the repo root):
 *
 *     npm install
 *     npm run build:assets
 *
 * Writes:
 *   assets/banner.png          2560 x 800, shown at the top of the README
 *   assets/social-preview.png  1280 x 640, upload it in Settings > Social preview
 *   assets/screenshots/*.webp  dark, light and phone views of the live page
 *
 * The digits are generated by index.html itself, so every build has a fresh, real layout.
 */

import { writeFile, mkdir } from 'node:fs/promises';
import { join } from 'node:path';
import { chromium } from 'playwright';
import { serve, ROOT } from '../scripts/serve.mjs';

const OUT = join(ROOT, 'assets');

const SHARED_CSS = `
html, body { margin: 0; padding: 0; background: #000; }
body { display: block; min-height: 0; overflow: hidden; }
body::before { z-index: 0; }
.mono { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; }
.eyebrow { letter-spacing: 3.5px; text-transform: uppercase; color: #FFC81E; font-weight: 700; margin: 0 0 18px; }
.title { font-family: Roboto, Arial, sans-serif; font-weight: 900; color: #f4f4f4; margin: 0; letter-spacing: -1.5px; line-height: .95; }
.sub { font-family: Roboto, Arial, sans-serif; color: #a8a8a8; margin: 20px 0 0; }
.chips { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 24px; }
.chip { display: inline-flex; align-items: center; gap: 8px; padding: 8px 15px; border-radius: 999px;
  border: 1px solid rgba(255,255,255,.14); font: 500 15px Roboto, Arial, sans-serif; color: #e6e6e6; }
.chip i { width: 10px; height: 10px; border-radius: 50%; display: block; }
.digit .digit-svg { width: 100%; height: auto; aspect-ratio: 232 / 292; display: block; }
`;

const BANNER_CSS = `
.banner { position: relative; z-index: 1; width: 1280px; height: 400px; box-sizing: border-box; padding: 0 56px 0 64px;
  display: grid; grid-template-columns: 1fr 600px; align-items: center; gap: 24px; }
.eyebrow { font-size: 14px; }
.title { font-size: 76px; }
.sub { font-size: 20px; }
.digits { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; }
`;

const PREVIEW_CSS = `
.preview { position: relative; z-index: 1; width: 1280px; height: 640px; box-sizing: border-box; padding: 64px;
  display: grid; grid-template-columns: 470px 1fr; gap: 40px; align-items: center; }
.eyebrow { font-size: 15px; }
.title { font-size: 92px; }
.sub { font-size: 23px; line-height: 1.4; }
.foot { margin-top: 36px; font-size: 15px; color: #8a8a8a; letter-spacing: 1px; }
.digits { display: grid; grid-template-columns: repeat(5, 1fr); gap: 22px 14px; }
`;

const CHIPS = `<div class="chips">
  <span class="chip"><i style="background:#EA2264"></i>Canvas pixel mask</span>
  <span class="chip"><i style="background:#0046FF"></i>SVG clipPath</span>
  <span class="chip"><i style="background:#6DE1D2"></i>Unique every load</span>
</div>`;

async function main() {
  const { server, base } = await serve();
  const browser = await chromium.launch();
  await mkdir(join(OUT, 'screenshots'), { recursive: true });

  /* 1. Let the real page generate all ten digits, then take its CSS and SVGs */
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto(`${base}/index.html`);
  await page.waitForSelector('.digit-wrapper .word');
  const { css, digits } = await page.evaluate(() => ({
    css: document.querySelector('style').textContent,
    digits: [...document.querySelectorAll('.digit-wrapper')].map(w => w.innerHTML),
  }));
  await page.close();

  // The page's CSS carries the embedded Roboto, so the images use the exact same font
  const pageCss = css;
  const doc = (extra, body) => `<!doctype html><html><head><meta charset="utf-8">
<style>${pageCss}${SHARED_CSS}${extra}</style></head>
<body class="anim-off">${body}</body></html>`;
  // Crop each SVG to the glyph itself (the page leaves room around it for the 3D tilt)
  const CROP = 'viewBox="34 108 232 292"';
  const digit = d => `<div class="digit">${digits[d].replace(/viewBox="[^"]*"/, CROP)}</div>`;

  async function render(viewport, scale, html, file) {
    const p = await browser.newPage({ viewport, deviceScaleFactor: scale });
    await p.setContent(html);
    await p.evaluate(() => document.fonts.ready);
    await p.waitForTimeout(300);
    await p.screenshot({ path: join(OUT, file) });
    await p.close();
  }

  /* 2. Banner */
  await render({ width: 1280, height: 400 }, 2, doc(BANNER_CSS, `<div class="banner">
    <div>
      <p class="eyebrow mono">Generative typography · one HTML file</p>
      <h1 class="title">Typography<br>Digits</h1>
      <p class="sub">The digits 0 to 9, packed with programming and data science words.</p>
      ${CHIPS}
    </div>
    <div class="digits">${[0, 1, 2, 3].map(digit).join('')}</div>
  </div>`), 'banner.png');

  /* 3. Social preview */
  await render({ width: 1280, height: 640 }, 1, doc(PREVIEW_CSS, `<div class="preview">
    <div>
      <p class="eyebrow mono">Generative typography</p>
      <h1 class="title">Typography<br>Digits</h1>
      <p class="sub">The digits 0 to 9, packed with programming and data science words.</p>
      <p class="foot mono">github.com/ShazMoghaddam/typography-digits<br>Shaz Moghaddam · London</p>
    </div>
    <div class="digits">${[...Array(10).keys()].map(digit).join('')}</div>
  </div>`), 'social-preview.png');

  /* 4. README screenshots of the real page, once the words have faded in */
  const shots = [
    { name: 'desktop-dark',  viewport: { width: 1440, height: 900 }, scale: 1, light: false },
    { name: 'desktop-light', viewport: { width: 1440, height: 900 }, scale: 1, light: true },
    { name: 'phone-dark',    viewport: { width: 390,  height: 844 }, scale: 2, light: false },
  ];
  for (const s of shots) {
    const p = await browser.newPage({ viewport: s.viewport, deviceScaleFactor: s.scale });
    await p.goto(`${base}/index.html`);
    await p.waitForSelector('.digit-wrapper .word');
    if (s.light) await p.click('label:has(#toggle-bg)');
    await p.evaluate(() => document.body.classList.add('anim-off'));   // every word at rest
    await p.waitForTimeout(1200);
    const png = await p.screenshot();
    // Re-encode as WebP in the browser itself: about a quarter of the PNG size, no extra dependency
    const webp = await p.evaluate(async b64 => {
      const img = new Image();
      img.src = `data:image/png;base64,${b64}`;
      await img.decode();
      const c = document.createElement('canvas');
      c.width = img.naturalWidth;
      c.height = img.naturalHeight;
      c.getContext('2d').drawImage(img, 0, 0);
      return c.toDataURL('image/webp', 0.9).split(',')[1];
    }, png.toString('base64'));
    await writeFile(join(OUT, 'screenshots', `${s.name}.webp`), Buffer.from(webp, 'base64'));
    await p.close();
  }

  await browser.close();
  server.close();
  console.log('wrote assets/banner.png, assets/social-preview.png and assets/screenshots/');
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});
